'use client';

/**
 * AlertBackup
 *
 * Self-contained component that manages its own visibility state.
 * Shows an alert when user has a secret key that needs to be backed up.
 * Hidden for a guest whose only identity is the pubky generated by the onboarding key step (no account yet).
 * No props needed - manages its own state internally.
 */
import { useEffect, useState } from 'react';
import { TriangleAlert } from 'lucide-react';
import { Container } from '@/atoms/Container/Container';
import { Typography } from '@/atoms/Typography/Typography';
import { Identity } from '@/libs/identity/identity';
import { hasAccountState } from '@/stores/auth/auth.selectors';
import { useAuthStore } from '@/stores/auth/auth.store';
import { hasSignupAttemptForSecretState } from '@/stores/onboarding/onboarding.selectors';
import { useOnboardingStore } from '@/stores/onboarding/onboarding.store';
import { DialogBackup } from '../DialogBackup/DialogBackup';
import { DialogConfirmBackup } from '../DialogConfirmBackup/DialogConfirmBackup';

export const AlertBackup = () => {
  const { secretKey } = useOnboardingStore();
  // A sign-up already started for this key may own an account the auth store holds no session for yet (#2955).
  const hasSignupAttempt = useOnboardingStore(hasSignupAttemptForSecretState);
  const currentUserPubky = useAuthStore((state) => state.currentUserPubky);
  const restoreStatus = useAuthStore((state) => state.restoreStatus);
  const hasAuthAccount = useAuthStore(hasAccountState);
  const hasAccount = hasAuthAccount || hasSignupAttempt;
  const needsSignIn = Boolean(
    restoreStatus === 'reauth-required' &&
    secretKey &&
    currentUserPubky &&
    Identity.tryZ32FromSecret(secretKey) === currentUserPubky,
  );
  const [showAlert, setShowAlert] = useState(false);
  useEffect(() => {
    if (secretKey) {
      setShowAlert(true);
    }
  }, [secretKey]);
  const handleDismiss = () => {
    setShowAlert(false);
  };

  // Don't show alert if there's no secretKey, it was dismissed, or the key has no account to lose yet (#2955)
  if (!secretKey || !showAlert || !hasAccount) {
    return null;
  }
  return (
    <Container className="flex-row flex-wrap items-center gap-3 rounded-lg bg-brand px-6 py-3">
      <Container className="flex-1 flex-row items-center gap-3">
        <TriangleAlert className="h-4 w-4 font-bold text-primary-foreground" />
        <Typography size="sm" className="font-bold whitespace-nowrap text-primary-foreground">
          <span className="md:hidden">{'Back up now'}</span>
          <span className="hidden md:inline">{'Back up now to avoid losing your account!'}</span>
        </Typography>
      </Container>
      <DialogBackup />
      <DialogConfirmBackup onConfirm={handleDismiss} />
      {needsSignIn && (
        <Typography size="sm" className="basis-full text-primary-foreground">
          Save your recovery phrase or encrypted file using Backup, then use it on the Sign In page to access your
          account again. If you already have a backup, you can use that instead.
        </Typography>
      )}
    </Container>
  );
};
